using namespace std;

long long tmp, n, k, len, L, kth, Res, Len;
map<long long, long long> vis;

inline long long Read() {
    long long t = 0, f = 1;
    char c = getchar();
    for (; c > 57 || c < 48; c = getchar())
        if (c == '-') f = -1;
    for (; c > 47 && c < 58; c = getchar())
        t = 10LL * t + c - 48;
    return t * f;
}

long long cal(long long now, long long len) {
    if (vis[now]) return vis[now];
    if (now == len) return 1;
    if (now == Len) return 0;
    return vis[now] = cal(now / 2, len) + cal(now - now / 2 - 1, len);
}

long long solve(long long l, long long r) {
    long long mid = (l + r) >> 1;
    if (r - l + 1LL == L) return l + (L + 1) / 2LL - 1LL;
    vis.clear();
    long long count = cal(mid - l, len);
    if (count < kth) {
        kth -= count;
        return solve(mid + 1, r);
    }
    return solve(l, mid - 1);
}

