    n = Read();
    k = Read();

    if (k == 1) {
        printf("1\n");
        return 0;
    }
    if (k == 2) {
        printf("%lld\n", n);
        return 0;
    }
    if (n == k) {
        printf("%lld\n", n - 1);
        return 0;
    }

    for (tmp = 1, len = n - 2, k -= 2;; len = (len - 1) / 2) {
        if (k <= tmp) {
            vis.clear();
            Len = len + 1;
            long long t = cal(n - 2, len);

            if (k <= t) {
                kth = k;
                L = len;
                Len = len + 1;
                Res += solve(2, n - 1);
            } else {
                kth = k - t;
                L = len + 1;
                Len = len;
                Res += solve(2, n - 1);
            }

            printf("%lld\n", Res);
            return 0;
        }
        k -= tmp;
        tmp *= 2;
    }
}

